generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?holdingGain) AS ?totalHoldingGain)
       (SUM(?rebalanceAmt) AS ?totalRebalancingAmount)
       (SUM(?scenarioChange) AS ?totalScenarioChange)
       (SUM(?cashFlowAmt) AS ?totalCashFlow)
WHERE {
  # Investor and its risk tolerance
  ?inv a wm:Investor ;
       wm:investorId ?invId ;
       wm:riskTolerance ?riskTolerance .

  # Holding gain per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?gain)) AS ?holdingGain) WHERE {
      ?h a wm:PortfolioHolding ;
         wm:investorId ?invId ;
         wm:currentValue ?curr ;
         wm:cost ?cost .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
    } GROUP BY ?invId
  }

  # Rebalancing amount per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?amt)) AS ?rebalanceAmt) WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?invId ;
          wm:amount ?amt .
    } GROUP BY ?invId
  }

  # Scenario allocation change per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?change)) AS ?scenarioChange) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?invId ;
          wm:currentAllocationPct ?curPct ;
          wm:newAllocationPct ?newPct .
      BIND (xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?change)
    } GROUP BY ?invId
  }

  # Cash flow amount per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?cfAmt)) AS ?cashFlowAmt) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?invId ;
          wm:amount ?cfAmt .
    } GROUP BY ?invId
  }
}
GROUP BY ?riskTolerance

